 const bomRows=()=>draft.bom.map((b,i)=>`<div class="product-bom-edit-row" data-pm-bom-row data-id="${esc(b.id||'')}"><input data-bom-part placeholder="Part number" value="${esc(b.partNumber||'')}"><input data-bom-desc placeholder="Description" value="${esc(b.description||'')}"><input data-bom-rev placeholder="Rev" value="${esc(b.revision||'A')}"><input data-bom-qty type="number" min="0.001" step="0.001" value="${Number(b.qtyPerUnit||1)}"><input data-bom-unit placeholder="Unit" value="${esc(b.unit||'pcs')}"><button type="button" class="button tiny danger" data-remove-bom="${i}">×</button></div>`).join('');
