function renderEquipmentMaster(){P.ensureEnterpriseModel(App.state);const today=P.todayISO(),careWeeks=Number(App.filters.careWeeks||26),due=App.state.equipment.filter(e=>(e.calibrationDue&&P.daysBetween(today,e.calibrationDue)<=30)||(e.maintenanceDue&&P.daysBetween(today,e.maintenanceDue)<=30)),trainingDue=(App.state.trainingCertificates||[]).filter(c=>c.status==='Valid'&&c.expiresAt&&P.daysBetween(today,c.expiresAt)<=60),care=new P.ResourceCareService().forecast(App.state,careWeeks);return pageHeader('Equipment, Calibration, Maintenance & Training','One readiness engine coordinates equipment calibration, preventive maintenance and training renewals against committed bookings and probability-weighted future demand.',`${btn('Calibration report','data-care-report="calibration"','button secondary')}${btn('Maintenance report','data-care-report="maintenance"','button secondary')}`)+`<div class="grid cols-4">${metric('Equipment',App.state.equipment.length)+metric('Equipment due ≤30 d',due.length)+metric('Training due ≤60 d',trainingDue.length)+metric('Scheduled readiness slots',(App.state.resourceCareBookings||[]).filter(x=>x.status==='Scheduled').length)}</div><div style="height:14px"></div><div class="card"><div class="section-title-row"><div><span class="eyebrow">OPTIMIZED READINESS PLAN</span><h2>Calibration, maintenance & training schedule</h2><div class="subtle">The optimizer searches exact conflict-free working slots before each due date, then scores them against committed work and probability-weighted future demand. Scheduled slots become real planner constraints, so AUTO-PLAN works around them.</div></div><label class="compact-select">Horizon<select id="careWeeks">${[13,26,52].map(n=>`<option value="${n}" ${careWeeks===n?'selected':''}>${n} weeks</option>`).join('')}</select></label></div>${carePlanTable(care)}</div><div style="height:14px"></div><div class="grid cols-2">${App.state.equipment.map(e=>{const certs=(App.state.calibrationCertificates||[]).filter(c=>c.equipmentId===e.id).sort((a,b)=>String(b.completedAt).localeCompare(String(a.completedAt))),latest=certs[0];return `<div class="card"><div class="section-title-row"><div><span class="pill">${esc(e.id)}</span><h3>${esc(e.name)}</h3></div>${status(P.equipmentReady(e,P.todayISO(),App.state)?'Ready':'Attention')}</div><div class="score-row"><span>Capability</span><strong>${esc(e.capability)}</strong></div><div class="score-row"><span>Calibration</span><strong>${esc(e.calibrationStatus)} · due ${P.formatDate(e.calibrationDue)}</strong></div><div class="score-row"><span>Latest certificate</span><strong>${latest?`${esc(latest.certificateNo)} · ${P.formatDate(latest.completedAt)}`:'No certificate'}</strong></div><div class="score-row"><span>Maintenance</span><strong>${esc(e.maintenanceStatus)} · due ${P.formatDate(e.maintenanceDue)}</strong></div><div class="score-row"><span>Equipment rate</span><strong>${P.currency(e.hourlyCost)} / h</strong></div><div class="route-toolbar equipment-actions">${btn('Certificates',`data-view-cal-certificates="${e.id}"`,'button tiny secondary')}${can('calibration:manage')||currentRole()==='administrator'?btn('+ Add certificate',`data-add-cal-certificate="${e.id}"`,'button tiny primary'):''}${can('calibration:manage')||currentRole()==='administrator'?btn('Complete calibration + certificate',`data-add-cal-certificate="${e.id}"`,'button tiny secondary'):''}${can('maintenance:manage')||currentRole()==='administrator'?btn('Record maintenance',`data-record-maintenance="${e.id}"`,'button tiny secondary'):''}${can('finance:manage')||currentRole()==='administrator'?btn('Edit rate',`data-edit-equipment-rate="${e.id}"`,'button tiny secondary'):''}</div></div>`}).join('')}</div>`}
function renderAdmin(){const profiles=Object.values(P.ASSURANCE_PROFILES);return pageHeader('Configuration & data','POC master data, customer profiles, build-purpose controls, export/import and future migration controls.')+`<div class="section-stack"><div class="card"><div class="section-title-row"><div><span class="eyebrow">BUILD PURPOSE CONTROLS</span><h2>E0 / E1 / V / P — what is included and excluded</h2><div class="subtle">Green = required, amber = conditional/lean, grey = deliberately not required. Product-safety work forces at least V.</div></div></div>${assuranceControlMatrix()}<div class="assurance-summary">${profiles.map(x=>`<div><b>${esc(x.code)}</b><span>${esc(x.description)}</span></div>`).join('')}</div></div><div class="grid cols-2"><div class="card"><div class="section-title-row"><h2>Customer profiles</h2>${currentRole()==='administrator'?btn('+ Add customer','data-add-customer','button small primary'):''}</div>${App.state.customers.map(c=>`<div class="callout" style="margin-bottom:8px"><div class="section-title-row"><h3>${esc(c.name)}</h3>${currentRole()==='administrator'?btn('Edit',`data-edit-customer="${c.id}"`,'button tiny secondary'):''}</div><p>Approvals: ${(c.requiredApprovals||[]).map(esc).join(', ')||'None'} · Retention ${esc(c.retention)} · Safe Launch ${c.safeLaunch?'Yes':'No'} · Product safety gate ${c.productSafetyGate?'Yes':'No'}</p>${c.evidenceExpectations?`<p style="margin-top:5px">Evidence: ${esc(c.evidenceExpectations)}</p>`:''}</div>`).join('')}</div><div class="card"><h2>Data portability</h2><p class="subtle">IndexedDB is the primary local store. UI and domain services use a repository abstraction so the persistence adapter can later be replaced.</p><div class="route-toolbar">${btn('Export JSON','data-export','button primary')}${btn('Import JSON','data-import','button secondary')}${btn('Reset demo data','data-reset','button danger')}</div><div class="callout"><h3>Schema / data version</h3><p>Schema ${App.state.schemaVersion} · data ${esc(App.state.dataVersion)} · app ${esc(P.VERSION)}</p></div></div></div></div>`}
function renderHelp(){const tasks=[['How engineering requests a prototype',['Open Prototype Requests and choose New prototype request.','Complete the six guided steps: need, objective, date/priority, configuration, characterisation, review.','Submit only after the review confirms required data.','Track Requested Date, Current Forecast, Readiness, Risk, Owner and Next Action in the workspace.']],['How lab triages a request',['Open the request workspace.','Review objective, configuration, required date and requested characterisation.','First assess exact material supply/arrival and confirm the actual process + requested test methods. Only then run AUTO-PLAN to create visible equipment/person bookings and a forecast.','Commit the forecast and continue once the timing basis is acceptable; resolve Action Centre items instead of creating detached notes.']],['How to issue the correct build material',['Tap Material source & feasibility.','Review the required part number, revision and quantity for each BOM line.','For Lab supplied, reserve only exact matching part/revision lots; for Engineering supplied, record expected arrival and then receive the actual lot. Issue is required before build start.','Unmatched legacy allocations remain visible for audit history but do not satisfy readiness.']],['How to select a standard process',['In the guided checklist, tap Process route & test-method assessment.','Insert a released library process.','Use process fit assessment for capability/material/geometry fit.','If outside the released envelope, start modified/new process development.']],['How to develop a new process',['Open Process Library or tap Process route & test-method assessment in the guided checklist.','Create a development workflow: plan → trials → parameters → risk → measurement/capability → Control Plan → work instruction → approval → release.','Compare trials and retain observations/evidence.','Release only when required gates are satisfied.']],['How to create/review a Control Plan',['Open the guided checklist and tap Control Plan, risk controls & special approvals.','Link controls to process steps and characteristics.','Ensure every special characteristic has an objective target and/or limits, method/gauge, evidence and reaction plan.','Request independent review; approved plans are revised rather than silently edited.']],['How to perform build-readiness review',['In the guided checklist, tap Build readiness.','Review each large readiness line.','For a blocker, read what/why/who/action/evidence/then.','Use controlled override only with authorised role and recorded reason/risk.']],['How a technician executes a build',['Switch to Prototype Technician.','In the guided checklist, tap Execute the build & capture evidence (or Execute engineering build & capture evidence for Rapid Engineering).','Follow the next guided operation, select a unit ID when the build purpose requires one, select equipment, and capture the evidence needed for that operation.','Guard rails prevent invalid calibration, unreleased process use or missing mandatory evidence.']],['How to record characterisation',['In the guided checklist, tap Characterise, evaluate & disposition exceptions.','Use manual entry or CSV import.','Results retain raw values, units, limits, serial, method, equipment/calibration, operator and timestamp.','Out-of-limit results create/maintain a quality hold until disposed.']],['How to manage a deviation/rework',['In the guided checklist, tap Characterise, evaluate & disposition exceptions.','Contain, investigate and choose an authorised disposition.','For rework, route back to the controlled process and reinspection step.','Close only when mandatory actions and verification are complete.']],['How to sign off/release a build',['Follow the guided checklist through Characterise, evaluate & disposition exceptions and Release approval.','Confirm serial counts, configuration, deviations, characterisation and special-characteristic status.','Release only when required approvals and release-hold checks pass.','Then use Deliver, retain records & close.']],['How to find a serial-number history',['Use global search or Serial History.','Open the serial to see request, configuration, material lots, process revisions, measurements, deviations and delivery.']],['How to manage calibration, maintenance & training',['Open Equipment, Calibration, Maintenance & Training.','Review the optimized readiness plan; it uses committed bookings plus probability-weighted future demand to find the lowest-load slot before each due date.','Schedule a proposed slot so AUTO-PLAN treats it as unavailable capacity.','Record completed calibration with certificate number, issuer, traceability/reference and evidence. Training renewals remain certificate-gated.']],['How to generate a prototype report',['Open Reports globally or use Deliver, retain records & close for request records.','Generate the report. Drafts show AUTO-GENERATED · NOT APPROVED.','Use print/save-PDF from the browser for a portable copy.','Organisation-specific approval and retention remain configurable.']]];
 return pageHeader('Help / User Manual','Task-based guidance for the actual proof-of-concept application.')+`<div class="card"><h2>Quick Start</h2><div class="quick-start"><div class="quick-step"><strong>1 · Pick a role</strong><span>Use Demo role at the top right.</span></div><div class="quick-step"><strong>2 · Open a scenario</strong><span>Prototype Requests includes 15 seeded automotive examples.</span></div><div class="quick-step"><strong>3 · Follow Next Action</strong><span>Each workspace explains blockers and direct resolution paths.</span></div><div class="quick-step"><strong>4 · Test controls</strong><span>Try AUTO-PLAN, readiness, execution, quality and report flows.</span></div></div></div><div style="height:14px"></div>${tasks.map(([t,steps])=>`<details class="help-task"><summary>${esc(t)}</summary><div class="help-body"><ol>${steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div></details>`).join('')}`
}
