function addCpCharacteristic(cpId){const cp=App.state.controlPlans.find(c=>c.id===cpId);openModal('Add Control Plan characteristic',`<div class="form-grid"><div class="field"><label>Characteristic ID</label><input id="newCpId" value="CHAR-${cp.characteristics.length+1}"></div><div class="field"><label>Characteristic</label><input id="newCpName" placeholder="e.g. Leak rate"></div><div class="field"><label>Classification</label><select id="newCpClass"><option value="">Normal</option><option>SC</option><option>PS</option></select></div><div class="field"><label>Process step number</label><input id="newCpStep" type="number" min="1" value="1"></div></div>`,`${btn('Cancel','data-modal-close','button')}${btn('Add & define','data-save-new-cp-char','button primary')}`);setTimeout(()=>{$('[data-save-new-cp-char]').onclick=async()=>{const name=$('#newCpName').value.trim();if(!name){toast('Characteristic name is required.',true);return}const c={id:$('#newCpId').value.trim()||P.uid('CHAR'),processStep:Number($('#newCpStep').value||1),characteristic:name,classification:$('#newCpClass').value,target:null,lsl:null,usl:null,unit:'',method:'',equipment:'',sampleSize:'100%',frequency:'Each unit',controlMethod:'Recorded result',role:'Technician',reactionPlan:'',evidence:''};cp.characteristics.push(c);cp.status='Draft';P.audit(App.state,'Control Plan characteristic added','Control Plan',cp.id,'—',c.id,name);await persist();editCpCharacteristic(cp.id,c.id)}},0)}
