function openRequestWizard(){App.wizardStep=0;App.wizardData={priority:'Normal',quantity:1,productId:App.state.products[0].id,customerId:'CUST-INTERNAL',engineeringTeam:App.state.teams[0],requiredDate:new Date(Date.now()+14*86400000).toISOString().slice(0,10),characterisation:['Functional verification'],materialOwnership:'Engineering supplied',materialSupplyOwner:App.state.identity.name,purpose:'Design learning / fit-check',assuranceProfile:'controlled'};renderWizard()}
function renderWizard(){const steps=['WHAT DO YOU NEED?','WHY DO YOU NEED IT?','WHEN DO YOU NEED IT?','WHAT CONFIGURATION?','WHAT CHARACTERISATION?','REVIEW & SUBMIT'];let body='';const d=App.wizardData,s=App.wizardStep;if(s===0)body=`<div class="form-grid"><div class="field full"><label>Request title</label><input id="wTitle" value="${esc(d.title||'')}"></div><div class="field"><label>Product/device</label><select id="wProduct">${App.state.products.map(p=>`<option value="${p.id}" ${d.productId===p.id?'selected':''}>${esc(p.family)} · ${esc(p.partNumber)}</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input id="wQty" type="number" min="1" value="${d.quantity||1}"></div><div class="field"><label>Engineering team</label><select id="wTeam">${App.state.teams.map(t=>`<option ${d.engineeringTeam===t?'selected':''}>${esc(t)}</option>`).join('')}</select></div><div class="field"><label>Customer / programme profile</label><select id="wCust">${App.state.customers.map(c=>`<option value="${c.id}" ${d.customerId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div></div>`;else if(s===1){const profiles=Object.values(P.ASSURANCE_PROFILES),recommended=P.recommendAssuranceProfile(d);body=`<div class="field"><label>Engineering objective / why do you need it?</label><textarea id="wObjective">${esc(d.objective||'')}</textarea><small>State the decision, learning or validation this build must enable.</small></div><div class="field" style="margin-top:12px"><label>Build purpose</label><select id="wPurpose">${['Quick engineering experiment','Design learning / fit-check','Process learning','Correlation','Failure analysis','Design validation (DV)','Customer / validation sample','Production-intent / PPAP support'].map(x=>`<option ${d.purpose===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Assurance / formality level</label><select id="wAssurance">${profiles.map(x=>`<option value="${x.id}" ${d.assuranceProfile===x.id?'selected':''}>${x.code} · ${esc(x.label)}</option>`).join('')}</select><small id="wAssuranceHint">Recommended from purpose: ${esc(P.ASSURANCE_PROFILES[recommended].code)} · ${esc(P.ASSURANCE_PROFILES[recommended].label)}. You may deliberately choose a different level; Product Safety automatically enforces at least Validation.</small></div><div class="assurance-choice-grid">${profiles.map(x=>{const summary=x.code==='E0'?'Includes safe/capable resources + basic evidence. No formal CP, serials or release.':x.code==='E1'?'Includes lean readiness + route/material evidence. Risk/CP only when needed; serials optional.':x.code==='V'?'Includes released methods, risk/CP controls, unit genealogy and formal release.':'Includes all V controls plus strongest production-intent/customer evidence.';return `<div class="assurance-choice level-${x.formalLevel}"><strong>${esc(x.code)} · ${esc(x.label)}</strong><span>${esc(x.tagline)}</span><small>${esc(summary)}</small></div>`}).join('')}</div>`}else if(s===2)body=`<div class="form-grid"><div class="field"><label>Required delivery date</label><input id="wDate" type="date" value="${esc(d.requiredDate)}"></div><div class="field"><label>Priority</label><select id="wPriority">${['Critical','High','Normal','Low'].map(x=>`<option ${d.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Delivery location</label><input id="wLocation" value="${esc(d.deliveryLocation||'Enschede Engineering')}"></div></div>`;else if(s===3)body=`<div class="form-grid"><div class="field"><label>Product revision</label><input id="wRev" value="${esc(d.productRevision||App.state.products.find(p=>p.id===d.productId)?.revision||'A')}"></div><div class="field"><label>Build maturity</label><select id="wMaturity">${['Concept','A-sample','B-sample','C-sample'].map(x=>`<option ${d.maturity===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Build configuration</label><textarea id="wConfig">${esc(d.configuration||'')}</textarea></div><div class="field"><label>BOM reference</label><input id="wBom" value="${esc(d.bomRef||'')}"></div><div class="field"><label>Material source</label><select id="wMatOwn"><option ${d.materialOwnership==='Engineering supplied'?'selected':''}>Engineering supplied</option><option ${d.materialOwnership==='Lab supplied'?'selected':''}>Lab supplied</option></select><small>Engineering supplied = engineering owns arrival to the lab. Lab supplied = planner reserves exact matching lab stock.</small></div><div id="wEngSupply" class="field full ${d.materialOwnership==='Lab supplied'?'hidden':''}"><div class="form-grid"><div class="field"><label>Who will supply it?</label><input id="wMatOwner" value="${esc(d.materialSupplyOwner||App.state.identity.name)}"></div><div class="field"><label>Expected arrival at lab</label><input id="wMatDate" type="date" value="${esc(d.materialSupplyDate||'')}"></div><div class="field full"><label>Supply/reference note</label><input id="wMatRef" value="${esc(d.materialSupplyReference||'')}" placeholder="e.g. parts held by design engineer / shipment reference"></div></div></div><div class="field full"><label><input id="wSafety" type="checkbox" style="width:auto;min-height:auto" ${d.productSafety?'checked':''}> Product-safety relevant</label></div></div>`;else if(s===4)body=`<div class="field"><label>Requested characterisation / required results</label><textarea id="wChar">${esc((d.characterisation||[]).join('\n'))}</textarea><small>One per line. Released lab standards currently include: ${(App.state.standardTests||[]).map(x=>esc(x.name)).join(', ')}. Unmatched requests will require a test-development estimate before planning.</small></div><div class="field" style="margin-top:12px"><label>Known special characteristics</label><textarea id="wSC">${esc((d.specialCharacteristics||[]).join('\n'))}</textarea></div>`;else body=`<div class="callout"><h3>Review before submission</h3><p>The request creates a controlled Draft. After submission the practical sequence is: material feasibility → process/test assessment → resource-based timing → controls/readiness → build.</p></div><div class="grid cols-2" style="margin-top:12px">${[['Need',`${d.quantity} × ${App.state.products.find(p=>p.id===d.productId)?.family}`],['Objective',d.objective||'—'],['Required date',P.formatDate(d.requiredDate)],['Priority',d.priority],['Material source',d.materialOwnership],['Assurance',`${P.ASSURANCE_PROFILES[d.assuranceProfile||P.recommendAssuranceProfile(d)].code} · ${P.ASSURANCE_PROFILES[d.assuranceProfile||P.recommendAssuranceProfile(d)].label}`],['Characterisation',(d.characterisation||[]).join(', ')||'—']].map(([a,b])=>`<div class="card"><div class="subtle">${esc(a)}</div><strong>${esc(b)}</strong></div>`).join('')}</div>`;openModal(`New prototype request · ${steps[s]}`,`<div class="wizard-shell"><div class="wizard-progress">${steps.map((_,i)=>`<div class="wizard-step ${i<s?'done':''} ${i===s?'active':''}"></div>`).join('')}</div>${body}</div>`,s===0?`${btn('Cancel','data-modal-close','button')}${btn('Next →','data-w-next','button primary')}`:s<steps.length-1?`${btn('Back','data-w-back','button')}${btn('Next →','data-w-next','button primary')}`:`${btn('Back','data-w-back','button')}${btn('Create draft','data-w-create','button primary')}`,true);bindWizard();}
function captureWizard(){const d=App.wizardData,s=App.wizardStep;if(s===0){d.title=$('#wTitle').value.trim();d.productId=$('#wProduct').value;d.quantity=Number($('#wQty').value);d.engineeringTeam=$('#wTeam').value;d.customerId=$('#wCust').value}else if(s===1){d.objective=$('#wObjective').value.trim();d.purpose=$('#wPurpose').value;d.assuranceProfile=$('#wAssurance').value}else if(s===2){d.requiredDate=$('#wDate').value;d.priority=$('#wPriority').value;d.deliveryLocation=$('#wLocation').value}else if(s===3){d.productRevision=$('#wRev').value;d.maturity=$('#wMaturity').value;d.configuration=$('#wConfig').value;d.bomRef=$('#wBom').value;d.materialOwnership=$('#wMatOwn').value;d.materialSupplyOwner=$('#wMatOwner')?.value.trim()||'';d.materialSupplyDate=$('#wMatDate')?.value||'';d.materialSupplyReference=$('#wMatRef')?.value.trim()||'';d.productSafety=$('#wSafety').checked;if(d.productSafety&&P.ASSURANCE_PROFILES[d.assuranceProfile]?.formalLevel<2)d.assuranceProfile='validation'}else if(s===4){d.characterisation=$('#wChar').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);d.specialCharacteristics=$('#wSC').value.split(/\n+/).map(x=>x.trim()).filter(Boolean)}}
function bindWizard(){const back=$('[data-w-back]'),next=$('[data-w-next]'),create=$('[data-w-create]'),src=$('#wMatOwn'),purpose=$('#wPurpose'),assurance=$('#wAssurance');if(purpose&&assurance){purpose.onchange=()=>{const rec=P.recommendAssuranceProfile({...App.wizardData,purpose:purpose.value});assurance.value=rec;const h=$('#wAssuranceHint'),p=P.ASSURANCE_PROFILES[rec];if(h)h.textContent=`Recommended from purpose: ${p.code} · ${p.label}. You can deliberately select a different level; Product Safety enforces at least Validation.`}};if(src)src.onchange=()=>{$('#wEngSupply')?.classList.toggle('hidden',src.value!=='Engineering supplied')};if(back)back.onclick=()=>{captureWizard();App.wizardStep--;renderWizard()};if(next)next.onclick=()=>{captureWizard();if(App.wizardStep===0&&(!App.wizardData.title||App.wizardData.quantity<1)){toast('Add a request title and quantity.',true);return}App.wizardStep++;renderWizard()};if(create)create.onclick=async()=>{const req=new P.RequestService(App.state).create(App.wizardData);await persist();closeModal();openRequest(req.id);toast('Draft prototype request created.')}}
function createControlPlan(requestId){const r=requestById(requestId),route=App.state.routes.find(x=>x.requestId===requestId);const chars=(r.specialCharacteristics||[]).map((sc,i)=>({id:`${sc}-${i+1}`,processStep:route?.steps[Math.min(i,Math.max(0,(route?.steps.length||1)-1))]?.order||1,characteristic:sc,classification:'SC',target:'Define target',lsl:null,usl:null,unit:'',method:'',equipment:'',sampleSize:'100%',frequency:'Each unit',controlMethod:'To be defined',role:'Quality / Technician',reactionPlan:'Hold affected serial; notify Quality; disposition before release',evidence:'Guided build result'}));if(!chars.length)chars.push({id:P.uid('CHAR'),processStep:route?.steps[0]?.order||1,characteristic:'Prototype functional acceptance',classification:'',target:'Pass',lsl:null,usl:null,unit:'',method:'Functional verification',equipment:'Applicable released equipment',sampleSize:'100%',frequency:'Each unit',controlMethod:'Recorded pass/fail',role:'Technician',reactionPlan:'Hold on failure; open deviation',evidence:'Guided build result'});const cp={id:P.uid('CP'),name:`${r.productFamily} Prototype Control Plan`,revision:'A',phase:'Prototype',status:'Draft',owner:App.state.identity.name,approvedBy:null,approvedAt:null,requestIds:[requestId],characteristics:chars};App.state.controlPlans.push(cp);r.controlPlanId=cp.id;P.audit(App.state,'Control Plan created','Control Plan',cp.id,'—','Draft',`Linked to ${requestId}`);persist().then(()=>{render();toast('Draft Control Plan created and linked to request.')})}
function advanceGateModal(id){const r=requestById(id),idx=P.GATES.indexOf(r.currentGate),next=P.GATES[idx+1];if(!next){toast('No later gate is available.');return}openModal(`Gate review · ${r.currentGate} → ${next}`,`<div class="callout"><h3>Objective gate review</h3><p>Record the evidence reviewed. Build Readiness and Release gates also run hard guard-rail checks.</p></div><div style="height:12px"></div><div class="field"><label>Evidence / review conclusion</label><textarea id="gateEvidence" placeholder="What evidence was reviewed and what conclusion was reached?"></textarea></div><div class="field" style="margin-top:12px"><label>Reason / decision note</label><input id="gateReason" placeholder="Controlled decision note"></div>`,`${btn('Cancel','data-modal-close','button')}${btn(`Advance to ${next}`,`data-confirm-gate="${id}"`,'button primary')}`);setTimeout(()=>{$('[data-confirm-gate]').onclick=async()=>{const evidence=$('#gateEvidence').value.trim(),reason=$('#gateReason').value.trim();if(!evidence){toast('Gate advancement requires evidence/review conclusion.',true);return}if(r.currentGate==='BUILD READINESS REVIEW'){const rr=new P.ReadinessService(App.state).evaluate(id);const hasOverride=(r.overrides||[]).some(o=>o.scope.toLowerCase().includes('readiness'));if(!rr.ready&&!hasOverride){toast(`Build Readiness cannot pass: ${rr.issues.length} unresolved blocker(s).`,true);return}}if(r.currentGate==='RELEASE APPROVAL'){try{new P.QualityService(App.state).releaseRequest(id)}catch(e){toast(e.message,true);return}App.state.serials.filter(s=>s.requestId===id&&s.status!=='Hold').forEach(s=>s.releaseState='Released')}else{const prev=r.status;r.status=r.currentGate=next;P.audit(App.state,'Lifecycle gate advanced','Request',id,prev,next,`${reason||'Gate review'} · Evidence: ${evidence}`)}await persist();closeModal();render();toast(`Gate advanced to ${r.currentGate}.`)}} ,0)}
async function submitRequest(id){try{new P.RequestService(App.state).submit(id);await persist();render();toast('Request submitted to lab triage.')}catch(e){toast(e.message,true)}}
async function ackDelivery(id){const r=requestById(id);const prev=r.status;r.status=r.currentGate='DELIVERED';App.state.serials.filter(s=>s.requestId===id&&s.releaseState==='Released').forEach(s=>{s.delivery=s.delivery||{date:P.todayISO(),recipient:App.state.identity.name,reference:P.uid('DEL')}});P.audit(App.state,'Delivery acknowledged','Request',id,prev,'DELIVERED','Engineering recipient acknowledgement');await persist();render();toast('Delivery acknowledged and audit trail updated.')}
async function advanceDevelopment(id){const dev=App.state.processDevelopments.find(d=>d.id===id);const order=['need','plan','trial','parameters','risk','measurement','capability','controlPlan','workInstruction','approval'];const next=order.find(k=>!dev.gates[k]);if(!next){toast('Development evidence gates are complete; release can now be performed.');return}dev.gates[next]=true;dev.status=next.toUpperCase().replaceAll('_',' ');if(next==='trial'&&!dev.trials.length)dev.trials.push({id:P.uid('TR'),date:P.todayISO(),material:'Demo development material',equipment:'EQ-001',operator:App.state.identity.name,parameters:{setpoint:'Defined in trial record'},result:'Pass',observations:'POC trial evidence captured'});P.audit(App.state,'Process development gate completed','Process Development',id,'Open',next,`Completed by ${App.state.identity.name}`);await persist();render();toast(`Development gate completed: ${next}.`)}
async function releaseDevelopment(id){try{const newId=new P.ProcessService(App.state).releaseDevelopment(id);const dev=App.state.processDevelopments.find(d=>d.id===id);const route=App.state.routes.find(r=>r.requestId===dev.requestId);const step=route.steps.find(s=>s.type!=='standard'&&(s.processId===dev.libraryCandidate||dev.name.includes(s.name.split(' — ')[0])));if(step){const proc=App.state.processes.find(p=>p.id===newId);step.processId=newId;step.processRevision='A';step.type='standard';step.readiness='pending';step.name=proc.name}await persist();render();toast(`Process released as ${newId} Rev A.`)}catch(e){toast(e.message,true)}}
