function parseCsv(text){text=String(text||'').replace(/^\uFEFF/,'');const first=(text.split(/\r?\n/).find(x=>x.trim())||''),count=(ch)=>(first.match(new RegExp(ch==='|'?'\\|':ch==='\\t'?'\\t':ch,'g'))||[]).length,delimiter=count(';')>count(',')?';':count('\\t')>count(',')?'\t':',';const rows=[];let row=[],field='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'){if(q&&n==='"'){field+='"';i++}else q=!q}else if(c===delimiter&&!q){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(field);field='';if(row.some(v=>String(v).trim()!==''))rows.push(row);row=[]}else field+=c}row.push(field);if(row.some(v=>String(v).trim()!==''))rows.push(row);rows.delimiter=delimiter;return rows}
function downloadTextFile(filename,text,mime='text/plain'){const blob=new Blob([text],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadCharacterisationTemplate(requestId){const r=requestById(requestId),profile=P.ensureAssuranceProfile(r),serial=(App.state.serials.find(s=>s.requestId===requestId)?.serial||''),test=(r.testRequirements||[])[0]?.name||(r.characterisation||[])[0]||'Characteristic',header='serial,characteristic,value,unit,lsl,usl,target,method,equipment,evidence\n',sample=`${profile.requires.serialisation?serial:''},${String(test).replace(/,/g,' ')},1.23,unit,,,1.2,Standard method,EQ-003,Example evidence`;downloadTextFile(`characterisation_template_${requestId}.csv`,header+sample,'text/csv')}
function importMeasurementCsv(requestId){const input=document.createElement('input');input.type='file';input.accept='.csv,text/csv';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;const txt=await file.text(),rows=parseCsv(txt);if(rows.length<2){toast('CSV has no data rows.',true);return}const aliases={serial:['serial','serial_number','unit_id','unit'],characteristic:['characteristic','test','measurement','parameter'],value:['value','result','measured_value'],unit:['unit','units'],lsl:['lsl','lower_limit','min'],usl:['usl','upper_limit','max'],target:['target','nominal'],method:['method','test_method','measurement_method'],equipment:['equipment','gauge','equipment_id'],evidence:['evidence','reference','comment']},rawHeaders=rows[0].map(x=>String(x).trim().toLowerCase()),canonical=h=>Object.entries(aliases).find(([,a])=>a.includes(h))?.[0]||h,headers=rawHeaders.map(canonical),profile=P.ensureAssuranceProfile(requestById(requestId)),required=profile.requires.serialisation?['serial','characteristic','value','unit']:['characteristic','value','unit'];if(required.some(k=>!headers.includes(k))){toast(`CSV requires: ${required.join(', ')}. Accepted aliases include unit_id, serial_number, result, lower_limit, upper_limit, test_method and gauge.`,true);return}const parseNum=v=>{const t=String(v??'').trim().replace(/\s/g,'').replace(rows.delimiter===';'?',':/,$/,rows.delimiter===';'?'.':'');return t!==''&&Number.isFinite(Number(t))?Number(t):null};let added=0,failed=0,skipped=0;for(const vals of rows.slice(1)){const row=Object.fromEntries(headers.map((h,i)=>[h,String(vals[i]??'').trim()])),serial=row.serial?App.state.serials.find(s=>s.requestId===requestId&&s.serial===row.serial):null;if(profile.requires.serialisation&&!serial){skipped++;continue}const value=parseNum(row.value);if(value===null){skipped++;continue}const eq=row.equipment?App.state.equipment.find(e=>e.id===row.equipment):null,cert=eq?P.validCalibrationCertificate(App.state,eq.id,P.todayISO()):null,calRequired=!!eq,calStatus=eq&&P.equipmentReady(eq,P.todayISO(),App.state)?'Valid':'Invalid',m={id:P.uid('MEAS'),requestId,serial:row.serial||null,characteristicId:row.characteristic,characteristic:row.characteristic,value,unit:row.unit,lsl:parseNum(row.lsl),usl:parseNum(row.usl),target:parseNum(row.target),method:row.method||'CSV import',equipment:eq?.id||row.equipment||'Unspecified',equipmentCalibrationStatus:calRequired?calStatus:'N/A',calibrationCertificateId:cert?.id||null,calibrationRequired:calRequired,operator:App.state.identity.name,timestamp:P.now(),pass:true,compliant:true,evidence:row.evidence||file.name,sourceFile:file.name};m.pass=new P.QualityService(App.state).evaluateMeasurement(m);m.compliant=m.pass&&(!m.calibrationRequired||m.equipmentCalibrationStatus==='Valid');App.state.measurements.push(m);added++;if(!m.pass||!m.compliant){failed++;if(!App.state.deviations.some(d=>d.measurementId===m.id))App.state.deviations.push({id:P.uid('DEVN'),requestId,serial:m.serial,step:m.characteristic,measurementId:m.id,measurement:`${m.characteristic}: ${m.value} ${m.unit}`,type:profile.formalLevel===0?'Engineering issue':'Nonconformance',status:'ISSUE DETECTED',releaseHold:profile.formalLevel>=1,containment:'Review affected output and contain if needed',investigation:'Pending',disposition:'Pending',approver:'',justification:'',actions:[{text:'Disposition / engineering decision',mandatory:true,closed:false}]})}}P.audit(App.state,'Characterisation CSV imported','Request',requestId,'—',`${added} rows from ${file.name}`,`${failed} failed/noncompliant; ${skipped} skipped`);await persist();render();toast(`Imported ${added} traceable result(s)${skipped?`; ${skipped} skipped`:''}${failed?`; ${failed} require action`:''}.`,failed>0)}catch(e){console.error(e);toast(`CSV import failed: ${e.message}`,true)}};input.click()}
